from pathlib import Path
from html.parser import HTMLParser
out=Path('/app/output')
class P(HTMLParser):
    def __init__(self): super().__init__(); self.title=''; self.intitle=False; self.links=[]; self.scripts=[]; self.styles=[]
    def handle_starttag(self,tag,attrs):
        d=dict(attrs)
        if tag=='title': self.intitle=True
        if tag=='a' and 'href' in d: self.links.append(d['href'])
        if tag=='script' and 'src' in d: self.scripts.append(d['src'])
        if tag=='link' and d.get('rel')=='stylesheet': self.styles.append(d.get('href'))
    def handle_endtag(self,tag):
        if tag=='title': self.intitle=False
    def handle_data(self,data):
        if self.intitle: self.title+=data
for f in sorted(out.glob('*.html')):
    p=P(); p.feed(f.read_text())
    missing=[]
    for href in p.links+p.scripts+p.styles:
        if href.startswith(('http','#','mailto:','tel:')): continue
        if not (out/href).exists(): missing.append(href)
    text=f.read_text()
    print(f.name, '| title:', p.title, '| missing:', missing, '| faq:', text.count('faq-item'), '| carousel:', 'data-carousel' in text)
